"use client";

import { useBookmarkStore } from "@/stores/bookmark-store";
import { cn } from "@/lib/cn";
import Icon from "@/components/ui/icon";

interface BookmarkButtonProps {
  movieId: number;
  variant?: "overlay" | "detail" | "inline";
  showLabel?: boolean;
  title?: string;
  className?: string;
}

export function BookmarkButton({
  movieId,
  variant = "overlay",
  showLabel = false,
  title,
  className,
}: BookmarkButtonProps) {
  const isBookmarked = useBookmarkStore((state) =>
    state.bookmarkedMovieIds.includes(movieId),
  );
  const toggleBookmark = useBookmarkStore((state) => state.toggleBookmark);

  const ariaLabel = title
    ? `${title} 북마크 토글`
    : isBookmarked
      ? "북마크 해제"
      : "북마크 추가";

  return (
    <button
      type="button"
      aria-pressed={isBookmarked}
      aria-label={ariaLabel}
      onClick={() => toggleBookmark(movieId)}
      className={cn(
        variant === "detail" &&
          "mt-4 inline-flex items-center gap-2 rounded-md border px-4 py-2 text-xs font-semibold transition-colors",
        variant === "overlay" &&
          "absolute right-2 top-2 inline-flex h-9 w-9 items-center justify-center rounded-full transition-colors backdrop-blur-sm",
        variant === "inline" &&
          "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-semibold transition-colors",
        variant === "detail" &&
          (isBookmarked
            ? "border-blue-600 bg-blue-600 text-white"
            : "border-gray-300 bg-white text-gray-600 hover:bg-gray-100"),
        variant === "overlay" &&
          (isBookmarked
            ? "bg-blue-600/90 text-white"
            : "bg-black/50 text-gray-200 hover:bg-black/70"),
        variant === "inline" &&
          (isBookmarked
            ? "bg-blue-600 text-white"
            : "bg-gray-200 text-gray-700 hover:bg-gray-300"),
        className,
      )}
    >
      <Icon
        name={isBookmarked ? "bookmark" : "bookmark-outline"}
        size={variant === "overlay" ? 20 : 16}
        className={cn("shrink-0", isBookmarked && "brightness-0 invert")}
      />
      {variant === "inline" && "북마크"}
      {showLabel && (isBookmarked ? "북마크 해제" : "북마크 추가")}
    </button>
  );
}
